  ('chamonix-france', '01F', 'Chamonix', 'France', 'Mont Blanc above, glaciers below — the mountaineer''s capital', 'live', 'verified', 'mountainValley', 'Haute-Savoie / French Alps', '{"ski","adventure"}', '{"alpine","dramatic","rugged"}', '{"comfort","premier","luxury"}', 'premier', 'core', '{"safety":{"advisory_level":"L2","posture":"book-freely","booking_hold":false,"notes":"Exercise increased caution (France-wide, mainly urban). In the valley the practical risk is the mountain rather than crime — high-alpine routes and the Vallée Blanche need a qualified guide.","source":"US State Dept L2 / French authorities","verified":"2026-06"},"timing":{"season":"Dec–Apr","best_months":[1,2,3],"notes":"Serious terrain; the Vallée Blanche is spring-dependent — check conditions."},"jewels":[{"name":"Aiguille du Midi cable car","tier":"comfort","when":"clear days","blurb":"3,842m and the roof of Europe in twenty minutes.","si":"adventure","commission":"Lift + experience partner"},{"name":"The Vallée Blanche with a guide","tier":"premier","when":"spring conditions","blurb":"20km off-piste from 3,842m to the valley — glacier, séracs, a mountain guide reading every step.","si":"adventure","commission":"Guide bureau — commission lane","source":"Compagnie du Mont-Blanc (Aiguille du Midi altitude and descent)"}],"faq":[{"q":"Do I need to be an expert to ski Chamonix?","a":"The linked areas (Brévent, Flégère, Grands Montets) have plenty for intermediates; the legendary off-piste and the Vallée Blanche need a qualified guide.","source":"Verified 2026-06"},{"q":"Can you ski the Vallée Blanche without a guide?","a":"No — it crosses a live glacier with crevasses and séracs. Always go with a certified mountain guide, and it''s spring-condition dependent.","source":"Compagnie des Guides"}]}'::jsonb, 5),
  ('st-moritz-switzerland', '01F', 'St. Moritz', 'Switzerland', 'Where alpine glamour was invented — and still lives', 'live', 'verified', 'mountainValley', 'Engadin / Graubünden', '{"ski","wellness"}', '{"alpine","refined","polished"}', '{"luxury","ultra"}', 'ultra', 'anchor', '{"safety":{"advisory_level":"L1","posture":"book-freely","booking_hold":false,"notes":"Normal precautions; alpine risk is weather + avalanche, managed by resort patrol — ski in-bounds and heed closures.","source":"US State Dept L1 / Swiss authorities","verified":"2026-06"},"timing":{"season":"Dec–Apr","best_months":[1,2,3],"notes":"High, sunny Engadin snow; Jan–Feb for the classic season and the frozen-lake events."},"jewels":[{"name":"A night at Badrutt''s, the lake frozen below","tier":"ultra","when":"peak season","blurb":"The birthplace of winter tourism, taken at full glamour.","si":"wellness","commission":"Hotel partner — commission lane"},{"name":"White Turf racing on the frozen lake","tier":"luxury","when":"February Sundays","blurb":"Thoroughbreds thunder across the frozen St. Moritzersee — a century-old spectacle.","si":"spectator","commission":"Event + hospitality partner"}],"faq":[{"q":"When is the frozen-lake season?","a":"The lake freezes solid enough for events from late January through February — White Turf racing, snow polo, and the gourmet festival all run then.","source":"St. Moritz Tourism"},{"q":"Is St. Moritz only for luxury travellers?","a":"The glamour is real, but the Engadin''s high, sunny slopes and the shared lift network serve every level — not every bed is a palace.","source":"Verified 2026-06"}]}'::jsonb, 6),
